import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0
    results = []
    while idx < len(input):
        t = int(input[idx])
        idx += 1
        for _ in range(t):
            n, m = map(int, input[idx].split())
            idx += 1
            graph = defaultdict(list)
            in_degree = [0] * (n + 1)
            for _ in range(m):
                a, b = map(int, input[idx].split())
                graph[a].append(b)
                in_degree[b] += 1
                idx += 1
            dp = [0] * (n + 1)
            dp[1] = 1
            queue = deque([1])
            visited = [False] * (n + 1)
            visited[1] = True
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if dp[u] == float('inf'):
                        dp[v] = float('inf')
                    elif dp[v] == 0:
                        dp[v] = dp[u]
                        queue.append(v)
                        visited[v] = True
                    elif dp[v] != float('inf') and dp[v] != dp[u]:
                        dp[v] = float('inf')
            for i in range(1, n + 1):
                if dp[i] == 0:
                    dp[i] = 0
                elif dp[i] == 1:
                    dp[i] = 1
                elif dp[i] == float('inf'):
                    dp[i] = -1
                else:
                    dp[i] = 2
            results.extend(dp[1:])
            if _ < t - 1:
                results.append('')
    print('\n'.join(map(str, results)))

main()
